insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-so-224","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The molal freezing-point depression constant $K_f$ is also called the","options":["cryoscopic constant","ebullioscopic constant","Henry constant","Faraday constant"],"answer_index":0,"explanation":"$K_f$ is the cryoscopic constant of the solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"},{"id":"che-so-225","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"$\\Delta T_f$ for a dilute non-electrolyte equals","options":["$K_f \\times$ molality","$K_b \\times$ molarity","$K_f / m$","$\\pi V$"],"answer_index":0,"explanation":"The working relation is $\\Delta T_f = K_f m$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"},{"id":"che-so-226","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Antifreeze in a car radiator works by","options":["depressing the freezing point of water","raising $K_H$ of air","increasing the vapour pressure of ice","nucleating ice crystals"],"answer_index":0,"explanation":"Ethylene glycol is a non-volatile solute that lowers the freezing point of the coolant.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"},{"id":"che-so-227","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"$K_f$ of water is about","options":["1.86 K kg mol⁻¹","0.52 K kg mol⁻¹","0.0821 L atm K⁻¹ mol⁻¹","100 °C"],"answer_index":0,"explanation":"The cryoscopic constant of water is 1.86 K kg mol⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"},{"id":"che-so-228","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Freezing-point depression is a","options":["colligative property","collisional nuclear effect","surface-tension effect only","colour property"],"answer_index":0,"explanation":"It depends on the number of solute particles in a given amount of solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"},{"id":"che-so-229","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At the freezing point of a dilute solution, the solid that separates is generally","options":["pure solid solvent","pure solid solute","a 1:1 compound always","ice that contains all the solute"],"answer_index":0,"explanation":"The solute stays in the liquid; the first solid is almost always the pure solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"},{"id":"che-so-230","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A larger $K_f$ at the same molality produces","options":["a larger depression","a smaller depression","no change","an elevation instead"],"answer_index":0,"explanation":"$\\Delta T_f$ scales with $K_f$ when m is fixed.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"},{"id":"che-so-231","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Common salt is scattered on icy roads because NaCl","options":["lowers the melting point of ice","raises the boiling point of ice","oxidises ice","absorbs all sunlight"],"answer_index":0,"explanation":"Dissolved ions depress the freezing point, so ice melts at the ambient winter temperature.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"},{"id":"che-so-232","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The unit of $K_f$ is","options":["K kg mol⁻¹","L atm mol⁻¹","mol L⁻¹","joule only"],"answer_index":0,"explanation":"The same dimensions as $K_b$: temperature over molality.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"},{"id":"che-so-233","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Camphor is a popular cryoscopic solvent because it has","options":["a very large $K_f$","a zero $K_f$","no melting point","$K_H = 0$"],"answer_index":0,"explanation":"A large cryoscopic constant magnifies $\\Delta T_f$ and makes molar-mass measurements easier.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"freezing-depression"},{"id":"che-so-234","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.25 m aqueous glucose solution ($K_f = 1.86$ K kg mol⁻¹) freezes lower than 0 °C by","options":["0.465 K","1.86 K","0.25 K","7.44 K"],"answer_index":0,"explanation":"$\\Delta T_f = 1.86 \\times 0.25 = 0.465$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"freezing-depression"},{"id":"che-so-235","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Ethylene glycol 12.4 g (62 g mol⁻¹) dissolved in 200 g water ($K_f = 1.86$) gives $\\Delta T_f$ of","options":["1.86 K","0.93 K","3.72 K","0.186 K"],"answer_index":0,"explanation":"n = 0.20 mol in 0.200 kg, so m = 1.0 mol kg⁻¹ and $\\Delta T_f = 1.86$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"freezing-depression"},{"id":"che-so-236","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A solution freezes at −0.372 °C. With $K_f = 1.86$ K kg mol⁻¹ the molality of the non-electrolyte is","options":["0.20 m","0.372 m","1.86 m","0.50 m"],"answer_index":0,"explanation":"$m = 0.372 / 1.86 = 0.20$ mol kg⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"freezing-depression"},{"id":"che-so-237","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Urea versus NaCl, both 0.10 molal in water: the larger freezing-point depression is shown by","options":["NaCl, which supplies more particles","urea","the two matching exactly","neither sample freezing"],"answer_index":0,"explanation":"NaCl gives two ions, so i ≈ 2 and $\\Delta T_f$ is about twice that of urea.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"freezing-depression"},{"id":"che-so-238","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A solute (M = 128 g mol⁻¹), 6.4 g, in 100 g of a solvent ($K_f = 5.0$ K kg mol⁻¹) depresses the freezing point by","options":["2.5 K","5.0 K","0.50 K","1.28 K"],"answer_index":0,"explanation":"n = 0.050 mol in 0.100 kg, so m = 0.50 mol kg⁻¹ and $\\Delta T_f = 5.0 \\times 0.50 = 2.5$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"freezing-depression"},{"id":"che-so-239","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.050 m AlCl3 solution, taken as fully split (i = 4) in water ($K_f = 1.86$ K kg mol⁻¹), has $\\Delta T_f$ nearest","options":["0.372 K","0.093 K","1.86 K","0.744 K"],"answer_index":0,"explanation":"$\\Delta T_f = 4 \\times 1.86 \\times 0.050 = 0.372$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"freezing-depression"},{"id":"che-so-240","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Acetic acid in benzene is 60% dimerised. For a 0.20 m solution ($K_f$ of benzene = 5.12 K kg mol⁻¹), $\\Delta T_f$ is nearest","options":["0.72 K","1.02 K","0.20 K","2.56 K"],"answer_index":0,"explanation":"For dimerisation $i = 1 - \\alpha/2 = 0.70$; $\\Delta T_f = 0.70 \\times 5.12 \\times 0.20 \\approx 0.72$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"freezing-depression"},{"id":"che-so-241","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Osmosis is the spontaneous flow of solvent through a semipermeable membrane toward the","options":["more concentrated solution","less concentrated solution","vapour phase","undissolved solid solute"],"answer_index":0,"explanation":"Solvent moves to dilute the side with the higher solute concentration.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure"},{"id":"che-so-242","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The extra pressure that must be applied on the solution to stop osmosis is called the","options":["osmotic pressure","vapour pressure","Henry pressure","atmospheric pressure only"],"answer_index":0,"explanation":"That balancing pressure is the definition of osmotic pressure $\\pi$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure"},{"id":"che-so-243","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"van’t Hoff wrote the dilute-solution law in the form","options":["$\\pi = CRT$","$\\pi = K_H x$","$\\pi = K_b m$","$\\pi = p^\\circ x$"],"answer_index":0,"explanation":"C is the molarity, R the gas constant and T the absolute temperature.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
